import 'package:flutter/material.dart';
class MazeRunnerGame extends StatefulWidget{const MazeRunnerGame({super.key});@override State<MazeRunnerGame> createState()=>_MazeRunnerGameState();}
class _MazeRunnerGameState extends State<MazeRunnerGame>{int p=0,moves=0;final path={0,1,2,6,10,14,15};void move(int d){final n=p+d;if(path.contains(n)&&n>=0&&n<16)setState((){p=n;moves++;});}@override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('Maze Runner')),body:Column(children:[Text('الحركات: $moves'),Expanded(child:GridView.builder(itemCount:16,gridDelegate:const SliverGridDelegateWithFixedCrossAxisCount(crossAxisCount:4),itemBuilder:(_,i)=>Container(margin:const EdgeInsets.all(3),decoration:BoxDecoration(color:i==p?Theme.of(c).colorScheme.primary:(path.contains(i)?Theme.of(c).colorScheme.surfaceContainerHighest:Theme.of(c).colorScheme.surface),borderRadius:BorderRadius.circular(8)),child:Center(child:Text(i==p?'🚀':i==15?'🏁':path.contains(i)?'':'×'))))),Wrap(alignment:WrapAlignment.center,children:[IconButton(onPressed:()=>move(-4),icon:const Icon(Icons.keyboard_arrow_up)),IconButton(onPressed:()=>move(-1),icon:const Icon(Icons.keyboard_arrow_left)),IconButton(onPressed:()=>move(1),icon:const Icon(Icons.keyboard_arrow_right)),IconButton(onPressed:()=>move(4),icon:const Icon(Icons.keyboard_arrow_down))]) ]));}